import java.io.*;
import java.util.*;

public class TwentyFive {
    public static void main(String[] args) throws Exception {
        DataInputStream dis = new DataInputStream(System.in);
        String pattern = readLine(dis);
        int total = 0;
        for (int val = 0; val < 100000000; val += 25) {
            String strVal = Integer.toString(val);
            if (strVal.length() != pattern.length()) continue;
            int xCharCode = -1;
            boolean isValid = true;
            for (int i = 0; i < pattern.length(); i++) {
                char pChar = pattern.charAt(i);
                char vChar = strVal.charAt(i);
                if (pChar == 'X') {
                    if (xCharCode == -1) {
                        xCharCode = vChar;
                    }
                    if (vChar != xCharCode) {
                        isValid = false;
                        break;
                    }
                } else if (pChar != '_') {
                    if (vChar != pChar) {
                        isValid = false;
                        break;
                    }
                }
            }
            if (isValid) total++;
        }
        System.out.println(total);
    }

    static String readLine(DataInputStream dis) throws IOException {
        StringBuilder sb = new StringBuilder();
        int ch;
        while ((ch = dis.read()) != -1) {
            if (ch == '\n') break;
            sb.append((char) ch);
        }
        return sb.toString();
    }
}
